import axios, { type AxiosInstance, type InternalAxiosRequestConfig } from 'axios'

let instance: AxiosInstance | null = null

export function initApiClient(baseURL: string): AxiosInstance {
  instance = axios.create({
    baseURL,
    headers: { 'Content-Type': 'application/json' },
    timeout: 10_000,
  })

  instance.interceptors.request.use((config: InternalAxiosRequestConfig) => {
    const token = localStorage.getItem('auth_token')
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }
    return config
  })

  instance.interceptors.response.use(
    (response) => response,
    (error) => {
      if (error.response?.status === 401) {
        localStorage.removeItem('auth_token')
        localStorage.removeItem('auth_user')
        localStorage.removeItem('auth_role')
        window.location.href = '/login'
      }
      return Promise.reject(error)
    },
  )

  return instance
}

export function getApiClient(): AxiosInstance {
  if (!instance) {
    throw new Error('API client not initialized. Call initApiClient() first.')
  }
  return instance
}
import { getApiClient } from '~/utils/api'
import type { ApiResponse, CreatePackageInput, Package } from '~/types'

export const packageService = {
  async listPackages(): Promise<Package[]> {
    const { data } = await getApiClient().get<ApiResponse<Package[]>>(
      '/api/v1/user/packages',
    )
    if (data.error) throw new Error(data.error)
    return data.data ?? []
  },

  async createPackage(input: CreatePackageInput): Promise<Package> {
    const { data } = await getApiClient().post<ApiResponse<Package>>(
      '/api/v1/admin/packages',
      input,
    )
    if (data.error) throw new Error(data.error)
    return data.data!
  },
}
import { packageService } from '~/services/package.service'
import type { CreatePackageInput, Package } from '~/types'

export function usePackages() {
  const packages = ref<Package[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  async function fetchPackages(): Promise<void> {
    loading.value = true
    error.value = null
    try {
      packages.value = await packageService.listPackages()
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to fetch packages'
    } finally {
      loading.value = false
    }
  }

  async function createPackage(input: CreatePackageInput): Promise<Package | null> {
    loading.value = true
    error.value = null
    try {
      const newPackage = await packageService.createPackage(input)
      packages.value = [newPackage, ...packages.value]
      return newPackage
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to create package'
      return null
    } finally {
      loading.value = false
    }
  }

  return { packages, loading, error, fetchPackages, createPackage }
}
import { getApiClient } from '~/utils/api'
import type { ApiResponse, Order, OrderStatus, TopupInput } from '~/types'

export const orderService = {
  async buyPackage(packageId: string): Promise<Order> {
    const { data } = await getApiClient().post<ApiResponse<Order>>(
      `/api/v1/user/packages/${packageId}/buy`,
    )
    if (data.error) throw new Error(data.error)
    return data.data!
  },

  async getUserOrders(): Promise<Order[]> {
    const { data } = await getApiClient().get<ApiResponse<Order[]>>(
      '/api/v1/user/orders',
    )
    if (data.error) throw new Error(data.error)
    return data.data ?? []
  },

  async requestRefund(orderId: string): Promise<void> {
    const { data } = await getApiClient().post<ApiResponse<{ message: string }>>(
      `/api/v1/user/orders/${orderId}/refund`,
    )
    if (data.error) throw new Error(data.error)
  },

  async topup(input: TopupInput): Promise<void> {
    const { data } = await getApiClient().post<ApiResponse<{ message: string }>>(
      '/api/v1/user/topup',
      input,
    )
    if (data.error) throw new Error(data.error)
  },

  async getAdminOrders(status: OrderStatus = 'pending'): Promise<Order[]> {
    const { data } = await getApiClient().get<ApiResponse<Order[]>>(
      '/api/v1/admin/orders',
      { params: { status } },
    )
    if (data.error) throw new Error(data.error)
    return data.data ?? []
  },

  async approveOrder(orderId: string): Promise<void> {
    const { data } = await getApiClient().put<ApiResponse<{ message: string }>>(
      `/api/v1/admin/orders/${orderId}/approve`,
    )
    if (data.error) throw new Error(data.error)
  },

  async rejectOrder(orderId: string): Promise<void> {
    const { data } = await getApiClient().put<ApiResponse<{ message: string }>>(
      `/api/v1/admin/orders/${orderId}/reject`,
    )
    if (data.error) throw new Error(data.error)
  },

  async approveRefund(orderId: string): Promise<void> {
    const { data } = await getApiClient().put<ApiResponse<{ message: string }>>(
      `/api/v1/admin/orders/${orderId}/refund`,
    )
    if (data.error) throw new Error(data.error)
  },
}
import { orderService } from '~/services/order.service'
import type { Order, OrderStatus } from '~/types'

export function useOrders() {
  const orders = ref<Order[]>([])
  const loading = ref(false)
  const actionLoading = ref<string | null>(null)
  const error = ref<string | null>(null)

  async function fetchUserOrders(): Promise<void> {
    loading.value = true
    error.value = null
    try {
      orders.value = await orderService.getUserOrders()
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to fetch orders'
    } finally {
      loading.value = false
    }
  }

  async function fetchAdminOrders(status: OrderStatus = 'pending'): Promise<void> {
    loading.value = true
    error.value = null
    try {
      orders.value = await orderService.getAdminOrders(status)
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to fetch orders'
    } finally {
      loading.value = false
    }
  }

  async function buyPackage(packageId: string): Promise<Order | null> {
    actionLoading.value = packageId
    error.value = null
    try {
      const order = await orderService.buyPackage(packageId)
      orders.value = [order, ...orders.value]
      return order
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to purchase package'
      return null
    } finally {
      actionLoading.value = null
    }
  }

  async function requestRefund(orderId: string): Promise<boolean> {
    actionLoading.value = orderId
    error.value = null
    try {
      await orderService.requestRefund(orderId)
      const idx = orders.value.findIndex((o) => o.id === orderId)
      if (idx !== -1) {
        orders.value[idx] = { ...orders.value[idx], status: 'refund_requested' }
      }
      return true
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to request refund'
      return false
    } finally {
      actionLoading.value = null
    }
  }

  async function approveOrder(orderId: string): Promise<boolean> {
    actionLoading.value = orderId
    error.value = null
    try {
      await orderService.approveOrder(orderId)
      orders.value = orders.value.filter((o) => o.id !== orderId)
      return true
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to approve order'
      return false
    } finally {
      actionLoading.value = null
    }
  }

  async function rejectOrder(orderId: string): Promise<boolean> {
    actionLoading.value = orderId
    error.value = null
    try {
      await orderService.rejectOrder(orderId)
      orders.value = orders.value.filter((o) => o.id !== orderId)
      return true
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to reject order'
      return false
    } finally {
      actionLoading.value = null
    }
  }

  async function approveRefund(orderId: string): Promise<boolean> {
    actionLoading.value = orderId
    error.value = null
    try {
      await orderService.approveRefund(orderId)
      orders.value = orders.value.filter((o) => o.id !== orderId)
      return true
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to approve refund'
      return false
    } finally {
      actionLoading.value = null
    }
  }

  return {
    orders,
    loading,
    actionLoading,
    error,
    fetchUserOrders,
    fetchAdminOrders,
    buyPackage,
    requestRefund,
    approveOrder,
    rejectOrder,
    approveRefund,
  }
}
